promql:
histogram_quantile(
  0.95,
  sum(
    rate(http_request_duration_seconds_bucket{client="ts-order-other-service", server="ts-order-other-service"}[60m])
  ) by (le)
)
and
avg_over_time(
  http_request_duration_seconds{client="ts-order-other-service", server="ts-order-other-service"}[1h]
) >= 0.01

bottomk(1,
  node_memory_Mapped_bytes
  * on(instance) group_left(node)
  (
    kube_pod_info{pod=~"ts-execute-service-.*"}
    * on(pod) group_left(node)
    (
      kube_pod_info{pod=~"ts-execute-service-.*"}
      * on(node) group_left(instance)
      (
        node_info{instance=~"10.176.122.151:9100|10.176.122.162:9100"}
      )
    )
  )
)

topk(1, 
  sum by (instance) (
    rate(node_cpu_seconds_total{mode="user"}[1m]) + rate(node_cpu_seconds_total{mode="system"}[1m])
  ) 
  and 
  node_load1 < 0.8 
  and 
  on (instance) 
  (
    kube_pod_info{pod=~"ts-gateway-service-.*"} 
    * on (pod) 
    kube_pod_info{node=~"k8s-node.*"}
  )
)

sum(
  node_memory_MemTotal_bytes
    * on(instance) group_left(node)
    (
      kube_pod_info{pod=~"nacosdb-mysql-.*"}
      * on(pod) group_left(node)
      (
        kube_pod_info{pod=~"nacosdb-mysql-.*"}
        * on(node) group_left(instance)
        (
          node_info{node=~"k8s-node1|k8s-node3|k8s-node5"}
        )
      )
    )
)

topk(1,
  sum by (server) (
    increase(
      http_requests_total{client="ts-rebook-service", status=~"5..", job="your_job_name"}[30m]
    )
  )
)

sum(
  increase(
    container_fs_usage_bytes{
      container="ts-auth-service",
      node="k8s-node2",
      device="/dev/sda"
    }[1h]
  )
) by (container, node, device)

histogram_quantile(
  0.99,
  sum(
    rate(
      http_request_duration_seconds_bucket{service="ts-verification-code-service", span_name=~"GET /api/v1/verifycode/generate|GET /api/v1/verifycode/verify/{verifyCode}"}[5m]
    )
  ) by (le, span_name)
)
